def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    if n < 10:
        return 'C'
    opp_def = sum(1 for a in op if a == 'D')
    opp_c = n - opp_def
    my_def = sum(1 for a in me if a == 'D')
    # If opponent is mostly nice, cooperate but punish recent defections.
    if opp_def <= n * 0.25:
        # Tit-for-tat with occasional random forgiveness
        if op[-1] == 'D':
            if n >= 2 and op[-2] == 'D' and me[-2] == 'D':
                return 'D'
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        return 'C'
    # If opponent is very exploitative, defect most of the time.
    if opp_def >= n * 0.75:
        if rng.random() < 0.9:
            return 'D'
        return 'C'
    # Mixed opponent: use a forgiving but retaliatory rule with detection
    # Count consecutive defections by opponent
    k = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            k += 1
        else:
            break
    if k >= 3:
        return 'D'
    if op[-1] == 'D':
        # Respond to defection, but sometimes forgive to avoid lock-in
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    # Cooperate unless we have been defecting too much recently
    if my_def > n * 0.4:
        if rng.random() < 0.2:
            return 'C'
        return 'D'
    # Occasionally defect to probe when near the end
    if n > 90 and opp_def < n * 0.5:
        if rng.random() < 0.15:
            return 'D'
    return 'C'
